-- Photo covers for the practice tests, replacing the line-art illustrations of V34 and V87 for 63 sections.
--
-- The photos are CC0 or public domain files from Wikimedia Commons, cropped to 2:1 and stored in the public "media"
-- bucket as practice/covers/<asset id>.webp (see scripts/practice-covers). The column holds the object key; Content builds
-- the URL with the media base URL, so a new bucket or domain is a configuration change. This migration does not upload
-- the files. Sections that are not listed keep their illustration.

UPDATE content_assets
SET media_reference = 'practice/covers/' || id || '.webp'
WHERE asset_type = 'IMAGE'
  AND id IN (
    '2d000000-0000-4000-8000-010000000001',
    '2d000000-0000-4000-8000-010000000002',
    '2d000000-0000-4000-8000-010000000003',
    '2d000000-0000-4000-8000-010000000004',
